LoadingCache<Integer,Integer> cache = CacheBuilder.newBuilder()
    .maximumSize(100)
    .build(new CacheLoader<Integer,Integer>() {
        public Integer load(Integer key) { return expensiveComputation(key); }
    });

cache.get(5); // miss - wywoluje CacheLoader.load(5), zapamietuje wynik
cache.get(5); // hit - z cache, BEZ ponownego liczenia

.get(key) rzuca checked ExecutionException; .getUnchecked(key) opakowuje w UncheckedExecutionException.

